        let handle = fs::read_to_string(handle_path)?;
        assert!(handle.contains(&format!("schema\t{SAVEPOINT_HANDLE_SCHEMA}\n")));
        assert!(handle.contains("label\trelease candidate\n"));
        assert!(handle.contains("checkpoint\tblake3:"));
